"""Functional HTTP export check only; generated bytes stay in memory, visual QA separate."""
import os,json,urllib.request,http.cookiejar,zipfile,io,hashlib
from pathlib import Path
from xml.etree import ElementTree
E=Path(__file__).resolve().parent
import argparse
parser=argparse.ArgumentParser();parser.add_argument('--policy',default='29');parser.add_argument('--run');args=parser.parse_args()
if args.policy not in {'28','29','33'}:raise SystemExit('Unsupported receipt policy')
run=args.run or f'codex-browser-policy{args.policy}-final'
report=json.loads((E/run/'ranking-focused-report.json').read_text())
o=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
def request(path,data):
 return o.open(urllib.request.Request('http://127.0.0.1:8501'+path,data=json.dumps(data).encode(),headers={'Origin':'http://127.0.0.1:8501','Content-Type':'application/json'}),timeout=90)
with request('/api/auth/login',{'tai_khoan':os.environ['DP_AUDIT_USER'],'mat_khau':os.environ['DP_AUDIT_PASSWORD']}) as r:json.load(r)
with request('/api/reports/export-docx',{'report_data':{'session_id':report['session_id'],'revision':report['revision']},'save_to_db':False}) as r:
 content=r.read();status=r.status;ctype=r.headers.get('Content-Type')
with zipfile.ZipFile(io.BytesIO(content)) as archive:text=''.join(ElementTree.fromstring(archive.read('word/document.xml')).itertext())
checks={'summary_present':report['executive_summary'] in text,'conclusion_present':report['conclusion']['answer'] in text,
 'findings_present':all(f['finding'] in text for f in report['key_findings']),
 'cohort_label_present':'Bottom 5' in text,'geography_warning_present':'2025' in text,
 'table_preview_disclosed':'Hiển thị 5 trên tổng số 5 dòng kết quả truy vấn' in text}
receipt={'status':'PASS_CONTENT_ONLY' if all(checks.values()) else 'FAIL_CONTENT','http_status':status,'content_type':ctype,
 'sha256':hashlib.sha256(content).hexdigest(),'bytes':len(content),'session_id':report['session_id'],'revision':report['revision'],
 'checks':checks,'visual_render':('Native Word fixture QA:12pages; exact HTTP export content checked here' if args.policy=='33' else 'NOT_RUN_NO_BUNDLED_RENDER_RUNTIME'),'save_to_db':False,'source_policy':'2026-10-22.cohort-scope.'+args.policy}
(E/f'codex-docx-export-policy{args.policy}-content-final.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2));print(json.dumps(receipt,ensure_ascii=False))
raise SystemExit(not all(checks.values()))
